mapper.select:
SELECT 

FROM project_assessment
WHERE 1=1

    AND project_id = #{param.projectId}


    AND project_id LIKE CONCAT('%', #{param.projectName}, '%')


    AND assessment_period = #{param.assessmentPeriod}


    AND assessment_type = #{param.assessmentType}


    AND assessment_status = #{param.assessmentStatus}


    AND assessment_level = #{param.assessmentLevel}


    AND assessor_id = #{param.assessorId}


    AND reviewer_id = #{param.reviewerId}


    AND assessment_date >= #{param.startDate}


    AND assessment_date <= #{param.endDate}


    AND total_score >= #{param.minScore}


    AND total_score <= #{param.maxScore}

ORDER BY 


        ${param.orderBy}

            ${param.orderDirection}



        assessment_date DESC, id DESC

SELECT COUNT(*) as totalProjects, COUNT(CASE WHEN assessment_status >= 2 THEN 1 END) as completedAssessments, ROUND(AVG(CASE WHEN assessment_status >= 2 THEN total_score END), 2) as averageScore, COUNT(CASE WHEN assessment_level = '优秀' THEN 1 END) as excellentCount, COUNT(CASE WHEN assessment_level = '良好' THEN 1 END) as goodCount, COUNT(CASE WHEN assessment_level = '一般' THEN 1 END) as averageCount, COUNT(CASE WHEN assessment_level = '合格' THEN 1 END) as qualifiedCount, COUNT(CASE WHEN assessment_level = '不合格' THEN 1 END) as unqualifiedCount FROM project_assessment WHERE 1=1
AND assessment_date >= #{startDate}
AND assessment_date <= #{endDate}
AND 1=1 -- 暂时忽略部门过滤，因为tbl_contract_project表不存在

SELECT ROW_NUMBER() OVER (ORDER BY pa.total_score DESC) as rank, pa.project_id, pa.project_id as project_name, pa.total_score, pa.assessment_level, 'N/A' as project_manager FROM project_assessment pa WHERE pa.assessment_status >= 2
AND pa.assessment_period = #{assessmentPeriod}
AND pa.assessment_type = #{assessmentType}
ORDER BY pa.total_score DESC
LIMIT #{limit}

SELECT assessment_level as level, COUNT(*) as count FROM project_assessment WHERE assessment_status >= 2
AND assessment_date >= #{startDate}
AND assessment_date <= #{endDate}
GROUP BY assessment_level ORDER BY CASE assessment_level WHEN '优秀' THEN 1 WHEN '良好' THEN 2 WHEN '一般' THEN 3 WHEN '合格' THEN 4 WHEN '不合格' THEN 5 ELSE 6 END
